import { initializeApp } from 'firebase/app';
import { getDatabase } from 'firebase/database';
import { getStorage } from 'firebase/storage';

const firebaseConfig = {
  apiKey: "AIzaSyDZE7NG5wheXpMhqgqhkmwHBQqQyLGgDtY",
  authDomain: "bbb-calendar.firebaseapp.com",
  databaseURL: "https://bbb-calendar-default-rtdb.asia-southeast1.firebasedatabase.app",
  projectId: "bbb-calendar",
  storageBucket: "bbb-calendar.appspot.com",
  messagingSenderId: "1098979667675",
  appId: "1:1098979667675:web:c0d1a0b8c1b8b8b8b8b8b8"
};

// Firebase'i başlat
const app = initializeApp(firebaseConfig);

// Realtime Database ve Storage referanslarını al
export const db = getDatabase(app);
export const storage = getStorage(app);
